// Generated by memory/deploy.sh from the files beside it. Edit those, not this.
export const FILES: Record<string, string> = {
  "claude-settings.json": "{\n  \"hooks\": {\n    \"SessionStart\": [{ \"hooks\": [{ \"type\": \"command\", \"command\": \"~/.config/memory/memory-hook SessionStart\" }] }],\n    \"UserPromptSubmit\": [{ \"hooks\": [{ \"type\": \"command\", \"command\": \"~/.config/memory/memory-hook UserPromptSubmit\" }] }],\n    \"PostToolUse\": [{ \"matcher\": \"mcp__memory__.*\", \"hooks\": [{ \"type\": \"command\", \"command\": \"~/.config/memory/memory-hook PostToolUse\" }] }],\n    \"Stop\": [{ \"hooks\": [{ \"type\": \"command\", \"command\": \"~/.config/memory/memory-hook Stop\" }] }],\n    \"PreCompact\": [{ \"hooks\": [{ \"type\": \"command\", \"command\": \"~/.config/memory/memory-hook PreCompact\" }] }],\n    \"SessionEnd\": [{ \"hooks\": [{ \"type\": \"command\", \"command\": \"~/.config/memory/memory-hook SessionEnd\" }] }]\n  }\n}\n",
  "codex-hooks.json": "{\n  \"hooks\": {\n    \"SessionStart\": [{ \"matcher\": \"startup|resume\", \"hooks\": [{ \"type\": \"command\", \"command\": \"MEMORY_AGENT=codex ~/.config/memory/memory-hook SessionStart\" }] }],\n    \"UserPromptSubmit\": [{ \"hooks\": [{ \"type\": \"command\", \"command\": \"MEMORY_AGENT=codex ~/.config/memory/memory-hook UserPromptSubmit\" }] }]\n  }\n}\n",
  "install.sh": "#!/bin/sh\n# Connect this computer's Claude Code and Codex to Wen's memory server. No checkout needed:\n#   curl -fsSL https://wlhlncmgjqyidosunugv.supabase.co/functions/v1/memory/install | sh\n# memory is allowlist only. A computer with no token signs in with a link to an allowlisted email, clicked from any\n# device, and gets a token of its own named after this computer (or MEMORY_DEVICE). On a work computer, set\n# MEMORY_HOOKS=metadata so memory keeps no prompts or tool output from its hooks. Rerun it any time: it replaces only\n# its own entries, the old kb ones too.\n# The token lands in ~/.config/memory/token, ~/.claude.json and ~/.codex/config.toml, all readable by you only.\n# `install.sh --update` is what memory-hook runs to update itself (R31). It asks nothing and keeps the token: it only\n# merges the hook config and replaces memory-hook, and only for the clients that already have a memory hook.\nset -eu\nDIR=$HOME/.config/memory\nif [ \"${1:-}\" = --update ]; then UPDATE=1; else UPDATE=; fi\nURL=${MEMORY_URL:-$([ -n \"$UPDATE\" ] && cat \"$DIR/url\" 2>/dev/null || true)}\nURL=${URL:-https://memory.heyclyde.me}\nDEVICE=${MEMORY_DEVICE:-$(hostname -s 2>/dev/null | tr 'A-Z' 'a-z' | tr -c 'a-z0-9._\\n-' '-')}\n\numask 077\n[ -n \"$UPDATE\" ] || mkdir -p \"$DIR\" \"$HOME/.claude\" \"$HOME/.codex\"\n\n# The files next to this script when run from a checkout, else fetched from the function.\nHERE=$(cd \"$(dirname \"$0\")\" 2>/dev/null && pwd || echo /nonexistent)\nif [ ! -f \"$HERE/memory-hook\" ]; then\n  HERE=$(mktemp -d)\n  trap 'rm -rf \"$HERE\"' EXIT\n  for f in memory-hook claude-settings.json codex-hooks.json; do\n    curl -fsS -m 15 \"$URL/install/files/$f\" -o \"$HERE/$f\"\n  done\nfi\n\nfield() { python3 -c 'import json, sys; print(json.load(sys.stdin).get(sys.argv[1]) or \"\")' \"$1\"; }\n\n# The HTTP status of an MCP initialize with this token: 200 when it's a live device token.\nprobe() {\n  curl -sS -m 15 -o /dev/null -w '%{http_code}' -X POST \"$URL/mcp\" -H \"Authorization: Bearer $1\" \\\n    -H \"Content-Type: application/json\" -H \"Accept: application/json, text/event-stream\" \\\n    --data '{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"protocolVersion\":\"2025-06-18\",\"capabilities\":{},\"clientInfo\":{\"name\":\"install.sh\"}}}' \\\n    || echo 000\n}\n\n# Sign in with a link to Wen's email and trade it for this computer's token. The link lands its PKCE code on the\n# function. Only this script holds the verifier, so the code alone signs nobody in.\nsign_in() {\n  conf=$(curl -fsS -m 15 \"$URL/install/config\")\n  auth=$(printf '%s' \"$conf\" | field auth); key=$(printf '%s' \"$conf\" | field key)\n  printf 'Your email: ' >/dev/tty; read -r email </dev/tty\n  # memory is allowlist only. Anyone else stops here, before any email is sent.\n  python3 -c 'import json, sys; print(json.dumps({\"email\": sys.argv[1]}))' \"$email\" |\n    curl -sS -m 15 -X POST \"$URL/install/check\" -H \"Content-Type: application/json\" --data-binary @- |\n    python3 -c 'import json, sys; d = json.load(sys.stdin); sys.exit(0 if d.get(\"allowed\") else d.get(\"error\") or \"not allowed\")'\n  set -- $(python3 -c 'import base64, hashlib, secrets\nv = secrets.token_urlsafe(48)\nprint(v, base64.urlsafe_b64encode(hashlib.sha256(v.encode()).digest()).rstrip(b\"=\").decode(), secrets.token_urlsafe(24))')\n  verifier=$1 challenge=$2 claim=$3\n  redirect=$(python3 -c 'import sys, urllib.parse; print(urllib.parse.quote(sys.argv[1], safe=\"\"))' \"$URL/install/approve?claim=$claim\")\n  python3 -c 'import json, sys; print(json.dumps({\"email\": sys.argv[1], \"create_user\": False, \"code_challenge\": sys.argv[2], \"code_challenge_method\": \"s256\"}))' \\\n    \"$email\" \"$challenge\" | curl -fsS -m 15 -o /dev/null -X POST \"$auth/otp?redirect_to=$redirect\" \\\n    -H \"apikey: $key\" -H \"Content-Type: application/json\" --data-binary @-\n  echo \"Check $email and click the sign-in link, from any device. Waiting...\" >/dev/tty\n  code=\n  for _ in $(seq 1 300); do\n    got=$(curl -sS -m 10 \"$URL/install/claim/$claim\" || true)\n    code=$(printf '%s' \"$got\" | field auth_code 2>/dev/null || true)\n    [ -n \"$code\" ] && break\n    sleep 3\n  done\n  [ -n \"$code\" ] || { echo \"No click within 15 minutes. Run it again.\" >&2; exit 1; }\n  jwt=$(python3 -c 'import json, sys; print(json.dumps({\"auth_code\": sys.argv[1], \"code_verifier\": sys.argv[2]}))' \"$code\" \"$verifier\" |\n    curl -fsS -m 15 -X POST \"$auth/token?grant_type=pkce\" -H \"apikey: $key\" -H \"Content-Type: application/json\" --data-binary @- |\n    field access_token)\n  curl -sS -m 15 -X POST \"$URL/devices/claim\" -H \"Authorization: Bearer $jwt\" -H \"Content-Type: application/json\" \\\n    --data \"{\\\"name\\\": \\\"$DEVICE\\\", \\\"hooks\\\": \\\"${MEMORY_HOOKS:-full}\\\"}\" | python3 -c 'import json, sys; d = json.load(sys.stdin); print(d.get(\"token\") or \"\"); sys.exit(0 if d.get(\"token\") else d.get(\"error\") or \"that email can'\"'\"'t connect a computer\")'\n}\n\n# memory-hook, moved into place in one step, so a hook running now never reads half a file. A checkout's copy has no\n# version yet, so it gets the server's. A fetched one was stamped by the server.\nput_hook() {\n  new=$DIR/.memory-hook.$$\n  if grep -q '^VERSION=@MEMORY_VERSION@$' \"$HERE/memory-hook\"; then\n    ver=$(curl -fsS -m 10 \"$URL/healthz\" 2>/dev/null | field version 2>/dev/null || true)\n    case $ver in ''|*[!0-9.]*) ver=@MEMORY_VERSION@ ;; esac\n    sed \"s/^VERSION=@MEMORY_VERSION@\\$/VERSION=$ver/\" \"$HERE/memory-hook\" > \"$new\"\n  else\n    cp \"$HERE/memory-hook\" \"$new\"\n  fi\n  chmod 700 \"$new\" && mv -f \"$new\" \"$DIR/memory-hook\"\n}\n\nif [ -z \"$UPDATE\" ]; then\n  TOKEN=${MEMORY_TOKEN:-$(cat \"$DIR/token\" 2>/dev/null || true)}\n  if [ -n \"$TOKEN\" ] && [ \"$(probe \"$TOKEN\")\" = 200 ]; then\n    echo \"This computer is already connected as $DEVICE, so no sign-in. Refreshing its Claude Code and Codex setup.\"\n  else\n    TOKEN=$(sign_in)\n  fi\n  case $(probe \"$TOKEN\") in\n    200) ;;\n    401) echo \"$URL refused the token\" >&2; exit 1 ;;\n    000) echo \"$URL is unreachable\" >&2; exit 1 ;;\n    *) echo \"$URL answered $(probe \"$TOKEN\")\" >&2; exit 1 ;;\n  esac\n\n  printf '%s\\n' \"$URL\" > \"$DIR/url\"\n  printf '%s\\n' \"$TOKEN\" > \"$DIR/token\"\n  printf '%s\\n' \"$DEVICE\" > \"$DIR/device-id\"\n  put_hook\nfi\n\n# Merge a {\"hooks\": {...}} snippet into a client's hooks file. Earlier memory and kb entries go, the user's own stay.\nmerge() {\n  python3 - \"$@\" <<'PY'\nimport json, sys\nfrom pathlib import Path\npath, ours = Path(sys.argv[1]).expanduser().resolve(), json.loads(Path(sys.argv[2]).read_text())[\"hooks\"]\ndoc = json.loads(path.read_text()) if path.exists() and path.read_text().strip() else {}\n\ndef stale(h):\n    \"\"\"Ours: a memory-hook or kb-hook entry, or a hand-written curl to /messages/codex from before either existed.\"\"\"\n    c = h.get(\"command\", \"\") if isinstance(h, dict) else \"\"\n    return \"memory-hook\" in c or \"kb-hook\" in c or (\"curl\" in c and \"/messages/codex\" in c)\n\ndef strip(groups):\n    \"\"\"Each group minus our entries. A group goes only when that leaves it empty.\"\"\"\n    kept = []\n    for g in groups:\n        if isinstance(g, dict) and isinstance(g.get(\"hooks\"), list):\n            left = [h for h in g[\"hooks\"] if not stale(h)]\n            if g[\"hooks\"] and not left:\n                continue\n            g[\"hooks\"] = left\n        kept.append(g)\n    return kept\n\ndef clean(table, events):\n    \"\"\"Strip our entries from these events. An event goes only when that leaves it empty.\"\"\"\n    for event in events:\n        if isinstance(table.get(event), list):\n            left = strip(table[event])\n            if left or not table[event]:\n                table[event] = left\n            else:\n                del table[event]\n\nclean(doc, ours)  # an old installer left Codex groups at the top level, where Codex never looks\nhooks = doc.setdefault(\"hooks\", {})\nclean(hooks, list(hooks))\nfor event, groups in ours.items():\n    hooks[event] = hooks.get(event, []) + groups\n# Written beside the file and moved over it, so a client reading it now never sees half of it.\ntmp = path.with_name(path.name + \".memory-tmp\")\ntmp.write_text(json.dumps(doc, indent=2) + \"\\n\")\ntmp.chmod(0o600)\ntmp.replace(path)\nPY\n}\n\n# A self-update stops here. The config goes first and memory-hook last, since the new version stamp is what says it's\n# done: if the merge fails, the old hook is still the old version and tries again.\nif [ -n \"$UPDATE\" ]; then\n  grep -qs memory-hook \"$HOME/.claude/settings.json\" && merge ~/.claude/settings.json \"$HERE/claude-settings.json\"\n  grep -qs memory-hook \"$HOME/.codex/hooks.json\" && merge ~/.codex/hooks.json \"$HERE/codex-hooks.json\"\n  put_hook\n  exit 0\nfi\n\n# Claude Code's CLI. The Claude desktop app bundles its own and keeps it off PATH, so fall back to its newest version.\nclaude_cli() {\n  command -v claude && return\n  app=\"$HOME/Library/Application Support/Claude/claude-code\"\n  for v in $(ls \"$app\" 2>/dev/null | sort -t. -k1,1nr -k2,2nr -k3,3nr); do\n    for bin in \"$app/$v\"/*/claude.app/Contents/MacOS/claude; do\n      [ -x \"$bin\" ] && { echo \"$bin\"; return; }\n    done\n  done\n  return 1\n}\n\nif CLAUDE=$(claude_cli); then\n  for old in kb memory; do \"$CLAUDE\" mcp remove \"$old\" --scope user >/dev/null 2>&1 || true; done\n  \"$CLAUDE\" mcp add --transport http --scope user memory \"$URL/mcp\" --header \"Authorization: Bearer $TOKEN\"\n  merge ~/.claude/settings.json \"$HERE/claude-settings.json\"\n  echo \"Claude Code: connected as $DEVICE. Restart it to load the hooks.\"\nelse\n  echo \"Claude Code: claude CLI not found, skipped.\"\nfi\n\n# Codex: hooks in ~/.codex/hooks.json, and the MCP server in config.toml with the header inline, since the Codex\n# desktop and IDE apps don't read your shell profile.\nmerge ~/.codex/hooks.json \"$HERE/codex-hooks.json\"\npython3 - \"$URL\" \"$TOKEN\" <<'PY'\nimport json, re, sys\nfrom pathlib import Path\npath = Path.home() / \".codex/config.toml\"\ntext = path.read_text() if path.exists() else \"\"\n# Drop any earlier [mcp_servers.kb] or [mcp_servers.memory] table and its subtables, up to the next unrelated table.\ntext = re.sub(r\"(?ms)^\\[mcp_servers\\.(kb|memory)(\\.[^\\]]*)?\\][^\\n]*\\n.*?(?=^\\[(?!mcp_servers\\.(kb|memory)[\\].])|\\Z)\", \"\", text).rstrip()\nblock = f'[mcp_servers.memory]\\nurl = {json.dumps(sys.argv[1] + \"/mcp\")}\\nhttp_headers = {{ Authorization = {json.dumps(\"Bearer \" + sys.argv[2])} }}\\n'\ntext = (text + \"\\n\\n\" if text else \"\") + block\ntry:\n    import tomllib\n    tomllib.loads(text)\nexcept ImportError:\n    pass\npath.write_text(text)\npath.chmod(0o600)\nPY\necho \"Codex: connected as $DEVICE. Run /hooks in the Codex CLI once to trust the two memory-hook entries.\"\n",
  "memory-hook": "#!/bin/sh\n# memory-hook <event>: forward a Claude Code or Codex hook payload (stdin) to Wen's memory server.\n# On SessionStart and UserPromptSubmit it also prints unread messages from Wen's other agents, which both clients add\n# to the agent's context. MEMORY_AGENT names the agent (claude by default, codex for Codex) for its events and its inbox.\n# The URL and token come from MEMORY_URL and MEMORY_TOKEN, else from ~/.config/memory.\n# It never blocks the agent: no config, a slow server or an error all exit 0 and print nothing.\n# It is a forwarder. For SessionStart, UserPromptSubmit and Stop it also prints whatever the server answers the event\n# with, untouched: Claude Code adds that to the agent's context, and acts on a Stop answer like {\"decision\":\"block\",...}.\n# Each call names this computer with x-memory-device: the installer's device name, else an id made once and kept in\n# ~/.config/memory/device-id.\n#\n# Self-update (R31). Every call sends VERSION, and the server answers with its own. When the server's is newer, an\n# installed hook starts `memory-hook --update` in the background, which fetches the current client files, checks them,\n# and has install.sh --update put them in place with the same token. Any failure leaves this client as it was, and a\n# failed try isn't repeated for 10 minutes. A client past the server's cutoff gets one line asking for a rerun of the installer.\n# The server stamps VERSION when it serves this file. A checkout's copy carries a placeholder, which counts as dev.\nVERSION=@MEMORY_VERSION@\ndir=$HOME/.config/memory\nurl=${MEMORY_URL:-$(cat \"$dir/url\" 2>/dev/null)}\ntoken=${MEMORY_TOKEN:-$(cat \"$dir/token\" 2>/dev/null)}\n[ -n \"$1\" ] && [ -n \"$url\" ] && [ -n \"$token\" ] || exit 0\n\n# True for YYYYMMDD.N and nothing else.\nisver() {\n  case $1 in\n    ''|*[!0-9.]*|.*|*.|*.*.*) return 1 ;;\n    *.*) return 0 ;;\n  esac\n  return 1\n}\n\n# True when version $1 is newer than $2. Both must pass isver.\nnewer() {\n  [ \"${1%%.*}\" -gt \"${2%%.*}\" ] || { [ \"${1%%.*}\" -eq \"${2%%.*}\" ] && [ \"${1#*.}\" -gt \"${2#*.}\" ]; }\n}\n\nupdate() {\n  # One update at a time. mkdir is atomic, and a lock older than 10 minutes belongs to a run that died.\n  find \"$dir/update.lock\" -maxdepth 0 -mmin +10 -exec rmdir {} \\; 2>/dev/null\n  mkdir \"$dir/update.lock\" 2>/dev/null || return 0\n  tmp=$(mktemp -d \"$dir/update.XXXXXX\") || { rmdir \"$dir/update.lock\"; return 1; }\n  trap 'rm -rf \"$tmp\"; rmdir \"$dir/update.lock\" 2>/dev/null' EXIT\n  for f in memory-hook claude-settings.json codex-hooks.json install.sh; do\n    curl -fsS -m 15 \"$url/install/files/$f\" -o \"$tmp/$f\" 2>/dev/null && [ -s \"$tmp/$f\" ] || return 1\n  done\n  # Only what looks whole and newer goes in: scripts that parse, with a shebang, JSON that loads, and a stamped version.\n  for f in memory-hook install.sh; do\n    [ \"$(head -c 2 \"$tmp/$f\")\" = '#!' ] && sh -n \"$tmp/$f\" 2>/dev/null || return 1\n  done\n  for f in claude-settings.json codex-hooks.json; do\n    python3 -c 'import json, sys; json.load(open(sys.argv[1]))' \"$tmp/$f\" 2>/dev/null || return 1\n  done\n  got=$(sed -n 's/^VERSION=//p' \"$tmp/memory-hook\" | head -1)\n  isver \"$got\" && newer \"$got\" \"$VERSION\" || return 1\n  sh \"$tmp/install.sh\" --update >/dev/null 2>&1\n}\n\nif [ \"$1\" = --update ]; then\n  if update; then rm -f \"$dir/update-failed\"; else : > \"$dir/update-failed\"; fi\n  exit 0\nfi\n\nisver \"$VERSION\" && sent=$VERSION || sent=dev\ndevice=$(cat \"$dir/device-id\" 2>/dev/null | tr -cd 'a-z0-9._-')\nif [ -z \"$device\" ]; then\n  device=$(od -An -N8 -tx1 /dev/urandom | tr -d ' \\n')\n  { mkdir -p \"$dir\" && printf '%s\\n' \"$device\" > \"$dir/device-id\"; } 2>/dev/null\nfi\n# The first call's headers say the server's version and where this client stands against it: -D - prints them. The\n# body goes to a file. -f keeps an error page out of it.\nbody=$(mktemp 2>/dev/null) || body=/dev/null\nheaders=$(curl -fsS -m 3 -D - -o \"$body\" -X POST \"$url/hooks/$1?agent=${MEMORY_AGENT:-claude}\" \\\n  -H \"Authorization: Bearer $token\" -H \"Content-Type: application/json\" \\\n  -H \"x-memory-client-version: $sent\" -H \"x-memory-device: $device\" \\\n  --data-binary @- 2>/dev/null | tr 'A-Z' 'a-z' | tr -d '\\r')\nheader() { printf '%s\\n' \"$headers\" | sed -n \"/^$1:/{s/^[^:]*: *//p;q;}\"; }\n\n# Only an installed hook updates itself. A checkout's, or a cloud session's, has no ~/.config/memory to replace.\nserver=$(header x-memory-version)\nif [ \"$0\" = \"$dir/memory-hook\" ] && isver \"$server\" && isver \"$VERSION\" && newer \"$server\" \"$VERSION\" &&\n  [ -z \"$(find \"$dir/update-failed\" -mmin -10 2>/dev/null)\" ]; then\n  nohup \"$0\" --update </dev/null >/dev/null 2>&1 &\nfi\n\ncase $1 in\n  SessionStart|UserPromptSubmit|Stop) [ -s \"$body\" ] && cat \"$body\" ;;\nesac\n[ \"$body\" = /dev/null ] || rm -f \"$body\"\ncase $1 in\n  SessionStart|UserPromptSubmit)\n    [ \"$(header x-memory-client-status)\" = expired ] &&\n      echo \"memory: this computer's client is out of date. Rerun \\`curl -fsSL $url/install | sh\\`, which needs no new sign-in.\"\n    curl -fsS -m 3 -H \"Authorization: Bearer $token\" -H \"x-memory-client-version: $sent\" \\\n      -H \"x-memory-device: $device\" \"$url/messages/${MEMORY_AGENT:-claude}\" 2>/dev/null ;;\nesac\nexit 0\n"
};
